USE master
GO

USE DB_AmeniScale
GO

SET NOCOUNT ON;
BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @CountryID INT;
    SELECT @CountryID = CountryID FROM Tbl_Countries WHERE CountryCode = 'CA';
    IF @CountryID IS NULL
    BEGIN
        SET @CountryID = SCOPE_IDENTITY();
    END

    DECLARE @SubdivisionID INT;
    SELECT @SubdivisionID = SubdivisionID FROM Tbl_Subdivisions WHERE SubdivisionName = 'Ontario' AND CountryID = @CountryID;
    IF @SubdivisionID IS NULL
    BEGIN
        VALUES (@CountryID, 'ON', 'Ontario', 'Province');
        SET @SubdivisionID = SCOPE_IDENTITY();
    END

    DECLARE @srcAmenityCategories TABLE (
        CategoryName NVARCHAR(100) NOT NULL,
        BaseWeight DECIMAL(5,2) NULL,
        IsNegative BIT NOT NULL
    );

        

    SELECT s.CategoryName, s.BaseWeight, s.IsNegative
    FROM @srcAmenityCategories s
    WHERE NOT EXISTS (
        SELECT 1 FROM Tbl_AmenityCategories ac WHERE ac.CategoryName = s.CategoryName
    );

    DECLARE @srcAmenities TABLE (
        CategoryName NVARCHAR(100) NOT NULL,
        Name NVARCHAR(255) NULL,
        City NVARCHAR(100) NULL,
        HouseNumber NVARCHAR(50) NULL,
        StreetName NVARCHAR(255) NULL,
        PostalCode NVARCHAR(20) NULL,
        Province NVARCHAR(100) NULL,
        Latitude DECIMAL(10,8) NULL,
        Longitude DECIMAL(11,8) NULL
    );














SELECT
    s.Name,
    ac.CategoryID,
    NULLIF(LTRIM(RTRIM(CONCAT(ISNULL(s.HouseNumber, ''),
                             CASE WHEN s.HouseNumber IS NULL OR s.StreetName IS NULL THEN '' ELSE ' ' END,
                             ISNULL(s.StreetName, '')))), '') AS Street,
    s.City,
    @SubdivisionID AS SubdivisionID,
    s.Latitude,
    s.Longitude,
    geography::Point(s.Latitude, s.Longitude, 4326)
FROM @srcAmenities s
JOIN Tbl_AmenityCategories ac ON ac.CategoryName = s.CategoryName
WHERE NULLIF(LTRIM(RTRIM(s.Name)), '') IS NOT NULL     -- ✅ skip null/blank names
  AND NOT EXISTS (
      SELECT 1
      FROM Tbl_Amenities a
      WHERE a.Name = s.Name
        AND ( (a.Latitude = s.Latitude) OR (a.Latitude IS NULL AND s.Latitude IS NULL) )
        AND ( (a.Longitude = s.Longitude) OR (a.Longitude IS NULL AND s.Longitude IS NULL) )
  );

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;